//! Parity test: the ported `rdrobust_bw` (sharp / no-covariate / hc0-hc1) vs R.
//! Cases come from `fixtures/bandwidth.json` and are regenerated by `tools/parity.py`.

use std::fs;
use std::path::PathBuf;

use rdrobust_core::{rdrobust_bw, Kernel, Vce};
use serde::Deserialize;

#[derive(Deserialize)]
struct Expected {
    v: f64,
    b: f64,
    r: f64,
    rate: f64,
}

#[derive(Deserialize)]
struct Fixture {
    id: String,
    x: Vec<f64>,
    y: Vec<f64>,
    #[serde(default)]
    t: Option<Vec<f64>>,
    #[serde(default)]
    z: Option<Vec<f64>>,
    #[serde(default)]
    dz: usize,
    #[serde(default)]
    covs_drop_coll: bool,
    c: f64,
    o: usize,
    nu: usize,
    o_b: usize,
    h_v: f64,
    h_b: f64,
    scale: f64,
    vce: String,
    nnmatch: usize,
    kernel: String,
    expected: Expected,
}

#[derive(Deserialize)]
struct FixtureBundle {
    schema_version: u32,
    oracle: OracleMetadata,
    cases: Vec<serde_json::Value>,
}

#[derive(Deserialize)]
struct OracleMetadata {
    package: String,
    version: String,
}

fn kernel(s: &str) -> Kernel {
    match s {
        "tri" => Kernel::Triangular,
        "epa" => Kernel::Epanechnikov,
        "uni" => Kernel::Uniform,
        other => panic!("unknown kernel {other}"),
    }
}

fn vce(s: &str) -> Vce {
    match s {
        "hc0" => Vce::Hc0,
        "hc1" => Vce::Hc1,
        "hc2" => Vce::Hc2,
        "hc3" => Vce::Hc3,
        "nn" => Vce::NearestNeighbor,
        other => panic!("unknown vce {other}"),
    }
}

/// Relative tolerance, matching the decisions.md continuous gate (~1e-8).
fn close(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1e-8 * a.abs().max(b.abs()).max(1.0)
}

#[test]
fn rdrobust_bw_matches_r() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../fixtures/bandwidth.json");
    let bundle: FixtureBundle = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(bundle.schema_version, 1);
    assert_eq!(bundle.oracle.package, "rdrobust");
    assert_eq!(bundle.oracle.version, "4.1.0");
    let mut n = 0;
    for case in bundle.cases.into_iter().filter(|case| case["kind"] == "bw") {
        let f: Fixture = serde_json::from_value(case).unwrap();
        let out = rdrobust_bw(
            &f.y,
            &f.x,
            f.t.as_deref(),
            f.z.as_deref(),
            f.dz,
            f.c,
            f.o,
            f.nu,
            f.o_b,
            f.h_v,
            f.h_b,
            f.scale,
            vce(&f.vce),
            f.nnmatch,
            f.covs_drop_coll,
            kernel(&f.kernel),
            None,
            None,
        );
        assert!(
            close(out.v, f.expected.v),
            "{} V: {} vs R {}",
            f.id,
            out.v,
            f.expected.v
        );
        assert!(
            close(out.b, f.expected.b),
            "{} B: {} vs R {}",
            f.id,
            out.b,
            f.expected.b
        );
        assert!(
            close(out.r, f.expected.r),
            "{} R: {} vs R {}",
            f.id,
            out.r,
            f.expected.r
        );
        assert!(
            close(out.rate, f.expected.rate),
            "{} rate: {} vs R {}",
            f.id,
            out.rate,
            f.expected.rate
        );
        n += 1;
    }
    assert!(n >= 7, "expected >= 7 bw fixtures, found {n}");
    eprintln!("rdrobust_bw parity: {n} fixtures matched R to 1e-8");
}
